WITH base AS (SELECT multiIf(latency_ms < 100, 1, latency_ms < 250, 2, latency_ms < 500, 3, latency_ms < 1000, 4, 5) AS `latencyBucketOrder`, multiIf(latency_ms < 100, '< 100 ms', latency_ms < 250, '100-250 ms', latency_ms < 500, '250-500 ms', latency_ms < 1000, '500 ms-1 s', '>= 1 s') AS `latencyBucket`, COUNT(events.event_id) AS `requests`, COUNT(if((events.status_code >= 500), events.event_id, NULL)) AS `serverErrors` FROM events WHERE toDateTime64(events.occurred_at, 9, 'UTC') BETWEEN ? AND ? GROUP BY `latencyBucketOrder`, `latencyBucket`) SELECT `latencyBucketOrder`, `latencyBucket`, `requests`, `serverErrors`, (toFloat64(`serverErrors`) / NULLIF(`requests`, 0)) AS `serverErrorRate` FROM base ORDER BY `latencyBucketOrder` ASC
